//! Raw FFI bindings to the CUDA driver API subset and the NVDEC decoder (cuvid).
//!
//! * `bindings.rs` is generated by bindgen from FFmpeg's `nv-codec-headers`
//!   (`dynlink_cuda.h`, `dynlink_nvcuvid.h`, MIT), see `scripts/regen.sh`.
//!   It is generated for the Windows target: the headers use `unsigned long`,
//!   which is 32-bit on Windows.
//! * The headers declare function *types* only; the entry points are resolved
//!   at run time from the driver DLLs (`nvcuda.dll`, `nvcuvid.dll`), so no CUDA
//!   SDK is needed to build. Signatures below mirror the `tcu*` typedefs.

#![allow(
    non_upper_case_globals,
    non_camel_case_types,
    non_snake_case,
    dead_code
)]
#![allow(clippy::all)]

mod bindings;

pub use bindings::*;

use core::ffi::{c_char, c_int, c_uint, c_ulonglong, c_void};

#[cfg(windows)]
pub const CUDA_LIBRARY: &str = "nvcuda.dll";
#[cfg(not(windows))]
pub const CUDA_LIBRARY: &str = "libcuda.so.1";
#[cfg(windows)]
pub const CUVID_LIBRARY: &str = "nvcuvid.dll";
#[cfg(not(windows))]
pub const CUVID_LIBRARY: &str = "libnvcuvid.so.1";

/// Declares a struct of function pointers loaded from one library.
macro_rules! dynlib {
    ($(#[$meta:meta])* $name:ident, $dll:expr, {
        $( $field:ident = $sym:literal : fn($($arg:ty),* $(,)?); )*
    }) => {
        $(#[$meta])*
        pub struct $name {
            _lib: libloading::Library,
            $( pub $field: unsafe extern "system" fn($($arg),*) -> CUresult, )*
        }

        impl $name {
            /// Loads the driver library and resolves every entry point.
            ///
            /// # Safety
            /// Loading a library runs its initialisation code.
            pub unsafe fn load() -> Result<Self, libloading::Error> {
                unsafe {
                    let lib = libloading::Library::new($dll)?;
                    $( let $field = *lib.get(concat!($sym, "\0").as_bytes())?; )*
                    Ok(Self { _lib: lib, $($field),* })
                }
            }
        }
    };
}

dynlib!(
    /// CUDA driver API entry points used by the decoder and the D3D11 interop.
    CudaLibrary, CUDA_LIBRARY, {
    init = "cuInit": fn(c_uint);
    device_get_name = "cuDeviceGetName": fn(*mut c_char, c_int, CUdevice);
    ctx_create = "cuCtxCreate_v2": fn(*mut CUcontext, c_uint, CUdevice);
    ctx_destroy = "cuCtxDestroy_v2": fn(CUcontext);
    ctx_push_current = "cuCtxPushCurrent_v2": fn(CUcontext);
    ctx_pop_current = "cuCtxPopCurrent_v2": fn(*mut CUcontext);
    ctx_synchronize = "cuCtxSynchronize": fn();
    get_error_name = "cuGetErrorName": fn(CUresult, *mut *const c_char);
    memcpy_2d = "cuMemcpy2D_v2": fn(*const CUDA_MEMCPY2D);
    memcpy_2d_async = "cuMemcpy2DAsync_v2": fn(*const CUDA_MEMCPY2D, CUstream);
    stream_create = "cuStreamCreate": fn(*mut CUstream, c_uint);
    stream_synchronize = "cuStreamSynchronize": fn(CUstream);
    stream_destroy = "cuStreamDestroy_v2": fn(CUstream);
    d3d11_get_device = "cuD3D11GetDevice": fn(*mut CUdevice, *mut c_void);
    graphics_d3d11_register_resource = "cuGraphicsD3D11RegisterResource":
        fn(*mut CUgraphicsResource, *mut c_void, c_uint);
    graphics_unregister_resource = "cuGraphicsUnregisterResource": fn(CUgraphicsResource);
    graphics_map_resources = "cuGraphicsMapResources":
        fn(c_uint, *mut CUgraphicsResource, CUstream);
    graphics_unmap_resources = "cuGraphicsUnmapResources":
        fn(c_uint, *mut CUgraphicsResource, CUstream);
    graphics_sub_resource_get_mapped_array = "cuGraphicsSubResourceGetMappedArray":
        fn(*mut CUarray, CUgraphicsResource, c_uint, c_uint);
});

dynlib!(
    /// NVDEC decoder and bitstream parser entry points.
    CuvidLibrary, CUVID_LIBRARY, {
    get_decoder_caps = "cuvidGetDecoderCaps": fn(*mut CUVIDDECODECAPS);
    create_decoder = "cuvidCreateDecoder": fn(*mut CUvideodecoder, *mut CUVIDDECODECREATEINFO);
    destroy_decoder = "cuvidDestroyDecoder": fn(CUvideodecoder);
    decode_picture = "cuvidDecodePicture": fn(CUvideodecoder, *mut CUVIDPICPARAMS);
    map_video_frame = "cuvidMapVideoFrame64":
        fn(CUvideodecoder, c_int, *mut c_ulonglong, *mut c_uint, *mut CUVIDPROCPARAMS);
    unmap_video_frame = "cuvidUnmapVideoFrame64": fn(CUvideodecoder, c_ulonglong);
    ctx_lock_create = "cuvidCtxLockCreate": fn(*mut CUvideoctxlock, CUcontext);
    ctx_lock_destroy = "cuvidCtxLockDestroy": fn(CUvideoctxlock);
    create_video_parser = "cuvidCreateVideoParser": fn(*mut CUvideoparser, *mut CUVIDPARSERPARAMS);
    parse_video_data = "cuvidParseVideoData": fn(CUvideoparser, *mut CUVIDSOURCEDATAPACKET);
    destroy_video_parser = "cuvidDestroyVideoParser": fn(CUvideoparser);
});
